    // Single-click reliability guard. A focused editor can emit change/blur on
    // pointerdown when the user clicks another control. Those handlers may call
    // draw(), which replaces the DOM before the target control receives click.
    // Defer only that redraw until the click completes.
    let pointerInteractionActive=false;
    let focusedEditorActive=false;
    let deferredInteractionDraw=false;
    let interactionReleaseQueued=false;

    function isCommitEditor(el){
      if(!el || !el.matches)return false;
      if(el.matches('textarea,[contenteditable="true"]'))return true;
      if(!el.matches('input'))return false;
      // Only free-form editors need protection from asynchronous background
      // redraws. Selects, checkboxes, radios and sliders are atomic controls:
      // deferring their redraw until blur makes the application appear stuck
      // until the user clicks somewhere else.
      const type=String(el.type||"text").toLowerCase();
      return !["checkbox","radio","range","button","submit","reset","file","color"].includes(type);
    }

    // Numeric inputs are typing-only by design. Studio hides browser-native
    // spinner chrome and does not inject custom increment/decrement controls.


    function refreshFocusedEditorState(){
      const active=root.ownerDocument?.activeElement;
      focusedEditorActive=!!(active && root.contains(active) && isCommitEditor(active));
      if(!focusedEditorActive && deferredInteractionDraw && !pointerInteractionActive){
        deferredInteractionDraw=false;
        draw();
      }
    }

    // Never replace the Studio DOM while a user is actively editing a value.
    // Runtime progress, bridge messages and status updates can otherwise call
    // draw() between keystrokes and make an input appear impossible to edit.
    root.addEventListener("focusin",ev=>{
      // Atomic controls must never inherit a stale "text editor focused" flag
      // from the control that previously had focus.
      focusedEditorActive=isCommitEditor(ev.target);
    },true);
    root.addEventListener("focusout",ev=>{
      if(!isCommitEditor(ev.target))return;
      queueMicrotask(refreshFocusedEditorState);
    },true);

    function releasePointerInteraction(){
      interactionReleaseQueued=false;
      if(!pointerInteractionActive && !deferredInteractionDraw)return;
      pointerInteractionActive=false;
      if(deferredInteractionDraw){
        deferredInteractionDraw=false;
        draw();
      }
    }

    root.addEventListener("pointerdown",ev=>{
      const active=root.ownerDocument?.activeElement;
      pointerInteractionActive=!!(active && root.contains(active) && isCommitEditor(active) && active!==ev.target && !active.contains?.(ev.target));
      interactionReleaseQueued=false;
    },true);
    root.addEventListener("click",()=>{
      if(!pointerInteractionActive||interactionReleaseQueued)return;
      interactionReleaseQueued=true;
      queueMicrotask(releasePointerInteraction);
    },true);
    root.addEventListener("pointerup",()=>{
      if(!pointerInteractionActive)return;
      // click normally follows pointerup; this is only a fallback for a
      // pointer interaction that does not produce click.
      setTimeout(()=>{if(pointerInteractionActive)releasePointerInteraction();},0);
    },true);
    root.addEventListener("pointercancel",releasePointerInteraction,true);

    // Every real Studio button gets immediate pressed feedback. Do not show a
