    function revealArtifactWorkspace(kind,artifactId=null){
      const workspace=kind==="data"?"data":"model";
      state.active_workspace=workspace;
      const ws=state.workspaces?.[workspace];
      if(ws){
        state.view_component_id=ws.view_component_id||ws.root_component_id;
        state.breadcrumbs=cp(ws.breadcrumbs||[{id:ws.root_component_id,name:ws.name||workspaceName()}]);
      }
      bottomView="outputs";
      bottomExpanded=true;
      outputDirectorySelection=artifactId||null;
    }

    function switchWorkspace(next){
      if(next===state.active_workspace)return;
      const oldKey=state.active_workspace||"model";
      const oldCanvas=root.querySelector(".mlb-canvas");
      if(oldCanvas){
        workspaceScroll[lastCanvasScrollKey||oldKey]={left:oldCanvas.scrollLeft,top:oldCanvas.scrollTop};
      }
      const oldSidebar=root.querySelector(".mlb-sidebar");
      if(oldSidebar){
        sidebarScroll[oldKey]={left:oldSidebar.scrollLeft,top:oldSidebar.scrollTop};
      }
      rememberWorkspaceView();
      runtimePanel=null;
      state.active_workspace=next;
      const ws=state.workspaces[next];
      state.view_component_id=ws.view_component_id||ws.root_component_id;
      state.breadcrumbs=cp(ws.breadcrumbs||[{id:ws.root_component_id,name:ws.name}]);
      selected=null;pendingPort=null;search="";
      switchingWorkspace=true;
      setStatus(workspaceName()+" opened.");
      // Workspace changes are atomic navigation actions, not text edits. Render
      // immediately so the selector and canvas can never get out of sync.
      draw(true);
    }

